mapper.select:
SELECT d.site_id AS `key`, d.site_id AS `label`, ROUND(, 3) AS `value`, COUNT(DISTINCT d.building_id) AS `count` FROM agg_building_daily d
AND d.stat_date >= #{startDate} AND d.stat_date <= #{endDate}
GROUP BY d.site_id ORDER BY `value` DESC

SELECT m.building_type_cn AS `key`, m.building_type_cn AS `label`, ROUND(, 3) AS `value`, COUNT(DISTINCT d.building_id) AS `count` FROM agg_building_daily d JOIN agg_building_monthly m ON m.building_id = d.building_id AND m.stat_year = d.stat_year AND m.stat_month = d.stat_month
AND d.stat_date >= #{startDate} AND d.stat_date <= #{endDate}
GROUP BY m.building_type_cn ORDER BY `value` DESC

SELECT d.season AS `key`, d.season AS `label`, ROUND(, 3) AS `value`, COUNT(*) AS `count` FROM agg_building_daily d
d.season IS NOT NULL AND d.stat_date >= #{startDate} AND d.stat_date <= #{endDate}
GROUP BY d.season ORDER BY `value` DESC

SELECT stat_hour AS `key`, CONCAT(LPAD(stat_hour, 2, '0'), ':00') AS `label`, ROUND( SUM(hvac_kwh) SUM(water_m3) SUM(carbon_kg) AVG(cop_sum / NULLIF(cop_cnt, 0)) SUM(electricity_kwh) , 3) AS `value`, COUNT(*) AS `count` FROM agg_time_hourly
AND stat_date >= #{startDate} AND stat_date <= #{endDate}
GROUP BY stat_hour ORDER BY stat_hour

SELECT b.data_grade AS `key`, CASE b.data_grade WHEN 'A' THEN 'A 级 · 建筑独立计量' ELSE 'B 级 · 站点分摊估算' END AS `label`, ROUND(, 3) AS `value`, COUNT(DISTINCT d.building_id) AS `count` FROM agg_building_daily d JOIN dim_building b ON b.building_id = d.building_id
AND d.stat_date >= #{startDate} AND d.stat_date <= #{endDate}
GROUP BY b.data_grade ORDER BY b.data_grade

SELECT CONCAT(m.stat_year, '-', LPAD(m.stat_month, 2, '0')) AS time, m.building_id AS buildingId, ROUND(SUM(m.electricity_kwh), 3) AS electricityKwh, ROUND(SUM(m.hvac_kwh), 3) AS hvacKwh, ROUND(SUM(m.water_m3), 3) AS waterM3, ROUND(SUM(m.carbon_kg), 3) AS carbonKg, ROUND(AVG(m.cop_avg), 3) AS cop, ROUND(AVG(m.air_temp_avg), 2) AS airTemperatureC, MAX(CASE WHEN m.anomaly_hours > 0 THEN 1 ELSE 0 END) AS anomalyFlag FROM agg_building_monthly m
AND CONCAT(m.stat_year, '-', LPAD(m.stat_month, 2, '0')) >= DATE_FORMAT(#{startDate}, '%Y-%m') AND CONCAT(m.stat_year, '-', LPAD(m.stat_month, 2, '0')) <= DATE_FORMAT(#{endDate}, '%Y-%m') AND m.anomaly_hours > 0
AND m.building_id IN #{bid}
AND m.site_id = #{siteId} AND m.building_type_cn = #{buildingType}
GROUP BY m.stat_year, m.stat_month, m.building_id ORDER BY m.stat_year, m.stat_month, m.building_id

SELECT DATE_FORMAT(f.ts, '%Y-%m-%d %H:00:00') AS time, f.building_id AS buildingId, ROUND(f.electricity_kwh, 3) AS electricityKwh, ROUND(f.hvac_kwh, 3) AS hvacKwh, ROUND(f.water_m3, 3) AS waterM3, ROUND(f.carbon_kg, 3) AS carbonKg, f.cop AS cop, f.air_temperature_c AS airTemperatureC, f.anomaly_flag AS anomalyFlag FROM fact_energy_hourly f
AND f.ts >= #{startDate} AND f.stat_year >= YEAR(#{startDate})
AND f.ts < DATE_ADD(#{endDate}, INTERVAL 1 DAY) AND f.stat_year <= YEAR(#{endDate})
AND f.anomaly_flag = 1
AND f.building_id IN #{bid}
ORDER BY f.ts LIMIT #{limit}

SELECT
    d.building_id AS buildingId,
    MAX(b.building_type_cn) AS buildingTypeCn,
    ROUND(SUM(d.electricity_kwh), 3) AS electricityKwh,
    ROUND(SUM(d.hvac_kwh), 3)        AS hvacKwh,
    ROUND(SUM(d.carbon_kg), 3)       AS carbonKg,
    ROUND(AVG(d.cop_avg), 3)         AS copAvg,
    ROUND(SUM(d.electricity_kwh) / NULLIF(MAX(b.area_m2), 0), 2) AS eui
FROM agg_building_daily d
JOIN dim_building b ON b.building_id = d.building_id

    AND d.stat_date >= #{startDate}
    AND d.stat_date <= #{endDate}

        AND d.building_id IN
        #{bid}

    AND d.site_id = #{siteId}
    AND b.building_type_cn = #{buildingType}

GROUP BY d.building_id
ORDER BY electricityKwh DESC
LIMIT #{limit}

SELECT b.building_id AS buildingId, b.site_id AS siteId, b.building_type_cn AS buildingTypeCn, b.data_grade AS dataGrade, b.area_m2 AS areaM2, b.electricity_kwh_year AS electricityKwhYear, b.eui_kwh_m2_year AS euiKwhM2Year, b.energy_grade AS energyGrade, b.cop_mean AS copMean, b.anomaly_rate AS anomalyRate FROM dim_building b
AND b.site_id = #{siteId} AND b.building_type_cn = #{buildingType}
AND (b.building_id LIKE CONCAT('%', #{keyword}, '%') OR b.building_type_cn LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY b.electricity_kwh_year DESC LIMIT #{limit}
